class Solution:
    def countAndSay(self, n: int) -> str:
        cur = "1"
        for _ in range(n - 1):
            nxt = []
            i = 0
            while i < len(cur):
                count = 1
                while i + 1 < len(cur) and cur[i] == cur[i + 1]:
                    i += 1
                    count += 1
                nxt.append(str(count) + cur[i])
                i += 1
            cur = "".join(nxt)
        return cur

