class Solution {
    public String countAndSay(int n) {
        String cur = "1";
        for (int step = 1; step < n; step++) {
            StringBuilder sb = new StringBuilder();
            int i = 0;
            while (i < cur.length()) {
                int count = 1;
                while (i + 1 < cur.length() && cur.charAt(i) == cur.charAt(i + 1)) {
                    i++;
                    count++;
                }
                sb.append(count).append(cur.charAt(i));
                i++;
            }
            cur = sb.toString();
        }
        return cur;
    }
}

